CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=(select auth.uid()));
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING(id=(select auth.uid()));
CREATE POLICY profiles_own_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=(select auth.uid()));
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING(id=(select auth.uid())) WITH CHECK(id=(select auth.uid()));
CREATE FUNCTION public.create_participant_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER participant_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_participant_profile();
ALTER TABLE public.participant_marks ADD COLUMN reviewed_at timestamptz, ADD COLUMN reviewed_by uuid, ADD COLUMN moderation_note text;
GRANT INSERT ON public.participant_marks TO authenticated;
GRANT UPDATE(status,reviewed_at,reviewed_by,moderation_note,latitude,longitude) ON public.participant_marks TO authenticated;
CREATE POLICY marks_own_insert ON public.participant_marks FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()) AND status='pending' AND consent_to_publish AND reviewed_at IS NULL AND reviewed_by IS NULL AND moderation_note IS NULL AND latitude IS NULL AND longitude IS NULL);
DROP POLICY marks_owner_read ON public.participant_marks;
DROP POLICY marks_public_read ON public.participant_marks;
CREATE POLICY marks_anon_read ON public.participant_marks FOR SELECT TO anon USING(status='approved' AND consent_to_publish);
CREATE POLICY marks_authenticated_read ON public.participant_marks FOR SELECT TO authenticated USING((status='approved' AND consent_to_publish) OR user_id=(select auth.uid()) OR public.has_role((select auth.uid()),'moderator') OR public.has_role((select auth.uid()),'admin'));
CREATE POLICY marks_moderator_update ON public.participant_marks FOR UPDATE TO authenticated USING(public.has_role((select auth.uid()),'moderator') OR public.has_role((select auth.uid()),'admin')) WITH CHECK(public.has_role((select auth.uid()),'moderator') OR public.has_role((select auth.uid()),'admin'));
CREATE FUNCTION public.validate_mark_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.status NOT IN ('pending','approved','rejected') THEN RAISE EXCEPTION 'Invalid status'; END IF;
IF length(btrim(NEW.country))=0 OR length(NEW.country)>100 OR length(coalesce(NEW.city,''))>120 THEN RAISE EXCEPTION 'Invalid location'; END IF;
IF TG_OP='UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status) THEN
IF OLD.status<>'pending' OR NEW.status NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Only pending marks can be reviewed'; END IF;
IF NOT(public.has_role(auth.uid(),'moderator') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Moderator required'; END IF;
IF NEW.status='approved' AND (NOT NEW.consent_to_publish OR NEW.latitude IS NULL OR NEW.longitude IS NULL) THEN RAISE EXCEPTION 'Consent and approximate coordinates required'; END IF;
NEW.reviewed_at=now(); NEW.reviewed_by=auth.uid();
END IF;
IF NEW.latitude IS NOT NULL AND (NEW.latitude < -60 OR NEW.latitude > 85) OR NEW.longitude IS NOT NULL AND (NEW.longitude < -180 OR NEW.longitude > 180) THEN RAISE EXCEPTION 'Invalid coordinates'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER validate_participant_mark BEFORE INSERT OR UPDATE ON public.participant_marks FOR EACH ROW EXECUTE FUNCTION public.validate_mark_review();
CREATE INDEX marks_user_idx ON public.participant_marks(user_id);
CREATE INDEX marks_queue_idx ON public.participant_marks(status,created_at);